{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Surveillance Data",
    "url": "http://localhost:7807",
    "widgets_json": {
      "alert_queue": {
        "name": "Alert Queue",
        "description": "Open surveillance alerts.",
        "endpoint": "/alert-queue",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "severity",
            "type": "text",
            "label": "Severity",
            "value": "high",
            "options": [
              {
                "label": "High",
                "value": "high"
              },
              {
                "label": "Medium",
                "value": "medium"
              },
              {
                "label": "Low",
                "value": "low"
              }
            ]
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "alert_id",
                "headerName": "Alert",
                "cellDataType": "text"
              },
              {
                "field": "desk",
                "headerName": "Desk",
                "cellDataType": "text"
              },
              {
                "field": "severity",
                "headerName": "Severity",
                "cellDataType": "text",
                "renderFn": "titleCase"
              },
              {
                "field": "age_days",
                "headerName": "Age (d)",
                "cellDataType": "number",
                "formatterFn": "int"
              }
            ]
          }
        }
      }
    },
    "apps_json": [
      {
        "name": "Surveillance Desk",
        "description": "Open surveillance alerts.",
        "tabs": {
          "alerts": {
            "id": "alerts",
            "name": "Alerts",
            "layout": [
              {
                "i": "alert_queue",
                "x": 0,
                "y": 0,
                "w": 24,
                "h": 10
              }
            ]
          }
        }
      }
    ]
  }
}
